#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// 1D layouts for vectors (all use dimension 'i')
	DEFINE_PROTO_STRUCT(x_layout, i_vec);

	// 2D layout for matrix A: dimensions 'i' (rows) and 'j' (columns)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	auto n  = x1 | get_length<'i'>();
	auto nA = A  | get_length<'i'>();

	// Precompute reciprocals to avoid divisions in the inner loops
	const num_t inv_n  = num_t(1.0) / num_t(n);
	const num_t inv_nA = num_t(1.0) / num_t(nA);

	// Initialize the four vectors
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = num_t(i % n) * inv_n;
		x2[state] = num_t((i + 1) % n) * inv_n;
		y_1[state] = num_t((i + 3) % n) * inv_n;
		y_2[state] = num_t((i + 4) % n) * inv_n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = num_t((i * j) % nA) * inv_nA;
	});
}

// computation kernel
// The kernel is intentionally kept out-of-line to make measurements cleaner.
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	// Views of y_1 and y_2 as vectors over 'j' (needed for y_[*][j])
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();
	auto y_2_j = y_2.get_ref() ^ noarr::rename<'i', 'j'>();

	// Transposed view of A to access A[j][i] as A_t[i][j]
	auto A_t = A.get_ref() ^ noarr::rename<'i', 'j', 'j', 'i'>();

	// We use two separate traversers for the two phases of the kernel.
	// For both of them we:
	//  - hoist 'i' to be the outer-most dimension,
	//  - iterate over that top-level dimension using a range-based for loop
	//    (optionally parallelized with OpenMP), and
	//  - inside each iteration, use a Noarr for_each over the remaining
	//    dimension 'j'.
	//
	// Within each outer-'i' iteration we keep x1[i] / x2[i] in a scalar
	// accumulator, so the corresponding vector element is loaded and stored
	// only once per i. This reduces memory traffic and gives the compiler a
	// simpler reduction pattern to vectorize.

	// Phase 1 traverser: works on (x1, y_1_j, A)
	auto trav1 = noarr::traverser(x1, y_1_j, A).order(noarr::hoist<'i'>());

	// Phase 2 traverser: works on (x2, y_2_j, A_t)
	auto trav2 = noarr::traverser(x2, y_2_j, A_t).order(noarr::hoist<'i'>());

#pragma scop
	// ---------------------------------------------------------------------
	// First part:
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x1[i] = x1[i] + A[i][j] * y_1[j];
	//
	// Implemented as:
	//   - top-level loop over 'i' via traverser iterator
	//   - inner Noarr for_each over remaining dimension 'j'
	// ---------------------------------------------------------------------
#pragma omp parallel for schedule(static)
	for (auto inner : trav1) {
		// 'inner' is a traverser with 'i' fixed and only 'j' remaining.
		// Extract the current i-index state once.
		auto si = inner.state(); // contains index_in<'i'>

		// Load x1[i] into a local accumulator
		num_t acc = x1[si];

		// Iterate over all j for this fixed i
		inner.for_each([&](auto s_ij) {
			// s_ij contains both 'i' and 'j'; all three structures
			// (A, y_1_j, x1) are compatible with it. For x1 we only
			// use the 'i' dimension, so the extra 'j' is ignored.
			acc += A[s_ij] * y_1_j[s_ij];
		});

		// Store the accumulated value back to x1[i]
		x1[si] = acc;
	}

	// ---------------------------------------------------------------------
	// Second part:
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x2[i] = x2[i] + A[j][i] * y_2[j];
	//
	// A_t is a pure view of A with dimensions renamed so that:
	//   A_t[i][j] == A[j][i]
	//
	// The parallelization pattern is identical to the first phase.
	// ---------------------------------------------------------------------
#pragma omp parallel for schedule(static)
	for (auto inner : trav2) {
		auto si = inner.state(); // index_in<'i'>

		// Local accumulator for x2[i]
		num_t acc = x2[si];

		inner.for_each([&](auto s_ij) {
			acc += A_t[s_ij] * y_2_j[s_ij];
		});

		x2[si] = acc;
	}
#pragma endscop
}

