		x2[state] = (num_t)(((i + 1) % n)) / n;
		y_1[state] = (num_t)(((i + 3) % n)) / n;
		y_2[state] = (num_t)(((i + 4) % n)) / n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	auto nA = A | get_length<'i'>();

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)((i * j) % nA) / nA;
	});
}

// computation kernel
//
// Original mathematical intent:
//
//   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
//   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
//
// Optimizations applied:
//   - Use traverser *ranges* to make the outer loop explicit over a chosen
//     dimension while still relying purely on Noarr abstractions.
//   - For the first part, iterate rows 'i' (outer) and columns 'j' (inner)
//     and keep a reference to x1[i] to avoid repeatedly re-resolving x1[i].
//   - For the second part, traverse A in a row‑major fashion by iterating
//     over 'j' rows of A_t and then over inner 'i', which improves cache
//     locality for the A[j][i] access.
//   - Hoist the read of y_2[j] out of the inner loop in the second part
//     so it is loaded exactly once per column j.
//
//   Optional parallelism:
//   - The first part has independent updates per i, so we can safely
//     parallelize the outer loop over 'i' with OpenMP if enabled.
//   - The second part cannot be naively parallelized over 'j' because
//     each iteration writes to all x2[i]; that would require either
//     atomics or additional reduction buffers, which would significantly
//     increase memory usage. To respect the 50% memory‑overhead limit,
//     we keep this part sequential.
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	using namespace noarr;

	// Views of y_1 and y_2 as vectors over 'j' (needed for y_[*][j])
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();
	auto y_2_j = y_2.get_ref() ^ noarr::rename<'i', 'j'>();

	// Transposed view of A to access A[j][i]
	auto A_t = A.get_ref() ^ noarr::rename<'i', 'j', 'j', 'i'>();

#pragma scop
	// ------------------------------------------------------------------
	// First part:
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x1[i] = x1[i] + A[i][j] * y_1[j];
	//
	// Implementation details:
	//   - We explicitly range over dimension 'i' so each iteration of the
	//     outer loop works on one row of A and the corresponding x1[i].
	//   - Within a row, we iterate over all 'j' using for_each.
	//   - We keep a reference 'x1_i' to x1[i] so that the index resolution
	//     is done once per row instead of once per element.
	// ------------------------------------------------------------------
	{
		auto trav = traverser(x1, y_1_j, A);

		// Outer loop over rows 'i'. Using a traverser range keeps the
		// loop structure explicit but fully Noarr-based.
		#ifdef _OPENMP
		#pragma omp parallel for schedule(static)
		#endif
		for (auto row_trav : trav.template range<'i'>()) {
			// row_trav has 'i' fixed; remaining free dimension is 'j'
			auto row_state = row_trav.state(); // contains only 'i'

			// Single reference to x1[i] for this row
			auto &x1_i = x1[row_state];

			// Inner loop over all columns 'j' for this fixed 'i'
			row_trav.for_each([&](auto state) {
				// state has both 'i' and 'j'
				x1_i += A[state] * y_1_j[state];
			});
		}
	}

	// ------------------------------------------------------------------
	// Second part:
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x2[i] = x2[i] + A[j][i] * y_2[j];
	//
	// Rewritten for better locality (mathematically equivalent):
	//   for (j = 0; j < N; j++)
	//     for (i = 0; i < N; i++)
	//       x2[i] = x2[i] + A[j][i] * y_2[j];
	//
	// Using A_t (A transposed view: dims 'j' x 'i'), iterating over 'j'
	// as the outer dimension gives row-major access to A_t and thus to
	// original A[j][i]. We also hoist y_2[j] out of the inner loop.
	// ------------------------------------------------------------------
	{
		auto trav_t = traverser(x2, y_2_j, A_t);

		// Outer loop over columns 'j' (rows of A_t)
		for (auto col_trav : trav_t.template range<'j'>()) {
			// col_trav has 'j' fixed; free dimension is 'i'
			auto col_state = col_trav.state(); // contains only 'j'

			// y_2[j] is constant for this whole column j; load it once
			const num_t y2_j_val = y_2_j[col_state];

			// Inner loop over all 'i' for this fixed 'j'
			col_trav.for_each([&](auto state) {
				// state has both 'j' and 'i'
				// x2 uses only 'i' and ignores 'j', which is correct for x2[i]
				x2[state] += A_t[state] * y2_j_val;
			});
		}
	}
#pragma endscop
}

} // namespace

