	auto n  = x1 | get_length<'i'>();
	auto nA = A  | get_length<'i'>();

	// Precompute reciprocals to replace divisions with cheaper multiplications
	const num_t inv_n  = num_t(1) / static_cast<num_t>(n);
	const num_t inv_nA = num_t(1) / static_cast<num_t>(nA);

	// Initialize the four vectors
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		const auto i = get_index<'i'>(state);

		const auto v0 = static_cast<num_t>(i % n);
		const auto v1 = static_cast<num_t>((i + 1) % n);
		const auto v3 = static_cast<num_t>((i + 3) % n);
		const auto v4 = static_cast<num_t>((i + 4) % n);

		x1[state] = v0 * inv_n;
		x2[state] = v1 * inv_n;
		y_1[state] = v3 * inv_n;
		y_2[state] = v4 * inv_n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	traverser(A).for_each([=](auto state) {
		const auto [i, j] = get_indices<'i', 'j'>(state);
		const auto prod   = static_cast<num_t>((i * j) % nA);
		A[state] = prod * inv_nA;
	});
}

// computation kernel
//
// Original mathematical specification:
//
//   for (i = 0; i < N; i++)
//     for (j = 0; j < N; j++)
//       x1[i] = x1[i] + A[i][j] * y_1[j];
//
//   for (i = 0; i < N; i++)
//     for (j = 0; j < N; j++)
//       x2[i] = x2[i] + A[j][i] * y_2[j];
//
// The implementation below keeps the same per-(i,j) update order for each i,
// but introduces per-row accumulators so that each x1[i]/x2[i] is loaded and
// stored only once. This significantly improves memory behavior without
// changing the arithmetic sequence for a fixed i.
//
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	// Views of y_1 and y_2 as vectors over 'j' (needed for y_[*][j])
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();
	auto y_2_j = y_2.get_ref() ^ noarr::rename<'i', 'j'>();

	// Transposed view of A to access A[j][i] while still using 'i' and 'j'
	auto A_t = A.get_ref() ^ noarr::rename<'i', 'j', 'j', 'i'>();

#pragma scop
	// --------------------------------------------------------------------
	// First part:
	//   x1[i] += sum_j A[i][j] * y_1[j]
	//
	// Optimization:
	//   - Traverse rows ('i') outermost, columns ('j') innermost
	//   - Use a per-row accumulator so that x1[i] is read and written once
	//   - The inner loop still walks A and y_1_j contiguously in 'j'
	//   - Parallelize across rows with OpenMP (if enabled)
	// --------------------------------------------------------------------
	{
		// Ensure 'i' is the outermost dimension driving the iterator
		auto trav_all = traverser(x1, y_1_j, A).order(hoist<'i'>());

		// Parallel over rows; when OpenMP is disabled, this pragma is ignored.
#pragma omp parallel for schedule(static)
		for (auto trav_i : trav_all) {
			// trav_i has 'i' fixed; remaining dimension is 'j'
			auto s_i = trav_i.state(); // state containing only index 'i'

			// Accumulate x1[i] in a register to minimize memory traffic
			num_t acc = x1[s_i];

			// Iterate over all columns 'j' in this row
			trav_i.for_each([&](auto state) {
				// state contains both 'i' (from trav_i.state()) and 'j'
				acc += A[state] * y_1_j[state];
			});

			// Store the final value of x1[i] once
			x1[s_i] = acc;
		}
	}

	// --------------------------------------------------------------------
	// Second part:
	//   x2[i] += sum_j A[j][i] * y_2[j]
	//
	// Optimization:
	//   - Use the transposed view A_t to access A[j][i] as A_t[i][j]
	//   - Again, traverse 'i' outermost, 'j' innermost
	//   - Use a per-row accumulator so that x2[i] is read and written once
	//   - Parallelize across rows with OpenMP (if enabled)
	// --------------------------------------------------------------------
	{
		// Again, hoist 'i' to be the outermost traversed dimension
		auto trav_all = traverser(x2, y_2_j, A_t).order(hoist<'i'>());

#pragma omp parallel for schedule(static)
		for (auto trav_i : trav_all) {
			// trav_i has 'i' fixed; remaining dimension is 'j'
			auto s_i = trav_i.state(); // state containing only index 'i'

			// Accumulate x2[i] in a register
			num_t acc = x2[s_i];

			trav_i.for_each([&](auto state) {
				// A_t[state] == A[j][i] for the corresponding (i,j)
				acc += A_t[state] * y_2_j[state];
			});

			x2[s_i] = acc;
		}
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// common length proto-structure for all dimensions
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto x1  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto x2  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);

	// initialize data
	init_array(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_mvt(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (prevents dead-code elimination), if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x1.get_ref());
		noarr::serialize_data(std::cerr, x2.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
