//   - keeps x1[i] in a scalar accumulator (acc_x1) per row
//   - hoists y_2[i] out of the inner loop
//   - updates x2 in a view where its index is named 'j'
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	// View of y_1 as a vector over 'j' (we need y_1[j])
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();

	// View of x2 as a vector over 'j' (we update x2[j])
	auto x2_j = x2.get_ref() ^ noarr::rename<'i', 'j'>();

#pragma scop
	// Fused kernel:
