	noarr::traverser(x1, x2_j, y_1_j, y_2, A)
		.template for_dims<'i'>([&](auto inner_trav_i) {

			// State with 'i' fixed for this row
			auto state_i = inner_trav_i.state();

			// Keep x1[i] in a register accumulator across the whole row
			num_t acc_x1 = x1[state_i];

			// y_2[i] is invariant across the inner 'j' loop
			const num_t y2_i = y_2[state_i];

			// Traverse all columns 'j' for the current row 'i'
			inner_trav_i.template for_each<'j'>([&](auto state_ij) {
				// state_ij has dimensions 'i' and 'j'

				// Read A[i][j] and y_1[j]
				const num_t a_ij = A[state_ij];
				const num_t y1_j = y_1_j[state_ij];

